using System;
using System.Collections.Generic;

namespace SurfOS.Users
{
    public enum AvatarSize { Small, Medium, Large }

    public sealed class AvatarDefinition
    {
        public AvatarDefinition(string id, string name, string[] small, string[] medium, string[] large)
        { Id = id; Name = name; Small = small; Medium = medium; Large = large; }
        public string Id { get; private set; }
        public string Name { get; private set; }
        public string[] Small { get; private set; }
        public string[] Medium { get; private set; }
        public string[] Large { get; private set; }
        public string[] Lines(AvatarSize size) { return size == AvatarSize.Small ? Small : size == AvatarSize.Medium ? Medium : Large; }
    }

