        private static AvatarDefinition A(string id, string name, string small, string medium, string large)
        { return new AvatarDefinition(id, name, small.Split('~'), medium.Split('~'), large.Split('~')); }
        public static IReadOnlyList<AvatarDefinition> All { get { return Items; } }
        public static AvatarDefinition Get(string id)
        {
            for (int i = 0; i < Items.Length; i++)
                if (string.Equals(Items[i].Id, id, StringComparison.OrdinalIgnoreCase) && Valid(Items[i])) return Items[i];
            return Items[0];
        }
        public static bool IsValid(string id)
        {
            for (int i = 0; i < Items.Length; i++)
                if (string.Equals(Items[i].Id, id, StringComparison.OrdinalIgnoreCase) && Valid(Items[i])) return true;
            return false;
        }
        private static bool Valid(AvatarDefinition item)
        { return LinesValid(item.Small) && LinesValid(item.Medium) && LinesValid(item.Large); }
        private static bool LinesValid(string[] lines)
        {
            if (lines == null || lines.Length == 0) return false;
            for (int i = 0; i < lines.Length; i++) if (string.IsNullOrEmpty(lines[i])) return false;
            return true;
        }
    }
